BEGIN;
-- PT111-S3-Q13
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND q.stimulus=$batch01$President of the Regional Chamber of Commerce: We are all aware of the painful fact that almost no new businesses have moved into our region or started up here over the last ten years. But the Planning Board is obviously guilty of a gross exaggeration in its recent estimate that businesses are leaving the region at the rate of about four a week. After all, there were never more than about one thousand businesses in the region, so if they were really leaving at such a rate, they would all have been gone long ago.$batch01$ AND q.prompt=$batch01$The argument is most vulnerable to criticism on the ground that it$batch01$ AND q.correct_choice=$batch01$D$batch01$) THEN RAISE EXCEPTION 'Question changed: PT111-S3-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S3-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND c.letter=$batch01$A$batch01$ AND c.choice_text=$batch01$focuses on what is going out of a system while ignoring the issue of what is coming into the system$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q13 A'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND c.letter=$batch01$B$batch01$ AND c.choice_text=$batch01$confuses a claim about a rate of change within a system with a claim about the absolute size of the system$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q13 B'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND c.letter=$batch01$C$batch01$ AND c.choice_text=$batch01$argues against a position simply by showing that the position serves the interest of the Planning Board$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q13 C'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND c.letter=$batch01$D$batch01$ AND c.choice_text=$batch01$treats a claim about what is currently the case as if it were a claim about what has been the case for an extended period$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q13 D'; END IF; END $guard$;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_answer_choices c JOIN lr_questions q ON q.id=c.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND c.letter=$batch01$E$batch01$ AND c.choice_text=$batch01$attacks what was offered as an estimate on the ground that it is not precise$batch01$) THEN RAISE EXCEPTION 'Choice changed: PT111-S3-Q13 E'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s JOIN lr_explanations e ON e.id=s.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND e.style IN ('single','standard')) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n JOIN lr_explanations e ON e.id=n.explanation_id JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation changed: PT111-S3-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch01$Conclusion$batch01$, $batch01$The Planning Board exaggerates when it estimates that businesses are leaving at about four a week.$batch01$), (1, $batch01$Evidence$batch01$, $batch01$The region has never had more than about 1,000 businesses; at four departures per week, all would have been gone long ago.$batch01$), (2, $batch01$Evaluate$batch01$, $batch01$The Board's estimate could describe the *current* departure rate. The president multiplies that rate across an unspecified long past. Even with hardly any arrivals in ten years, departures might have been slower before and increased recently. For instance, a rate of four this week says nothing about how many left each week five years ago.$batch01$), (3, $batch01$Goal$batch01$, $batch01$Find the time shift from a present rate to a sustained historical rate.$batch01$)) v(position,label,body) WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch01$A$batch01$, $batch01$The speaker explicitly notes that almost no new businesses have arrived. The mistake is extending the departure rate backwards, not ignoring incoming businesses.$batch01$), ($batch01$B$batch01$, $batch01$A rate of four departures per week and a stock of at most 1,000 businesses are different quantities, but comparing them *would* be informative if the rate had lasted long enough. The unsupported move is assuming that it did.$batch01$), ($batch01$C$batch01$, $batch01$The president does not attack the Board's interests or motives. He attacks its estimate with a numerical argument.$batch01$), ($batch01$D$batch01$, $batch01$"Leaving ... at the rate of about four a week" reports a rate now. The president calculates as though businesses had been leaving at that rate for an extended time. That historical premise was never supplied.$batch01$), ($batch01$E$batch01$, $batch01$The president calls the estimate a gross exaggeration, not merely imprecise. His reasoning does not depend on pretending that "about four" is exact.$batch01$)) v(letter,body) WHERE q.qid=$batch01$PT111-S3-Q13$batch01$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
